5477	// The history guard. A provider bills the part of a request it has seen
5478	// before (its prompt cache) at a fraction of the full price, and it finds
5479	// that part only when the new request opens with it unchanged. So the first
5480	// request of every turn must open with the whole of the last request the turn
5481	// before sent: tools, system prompt, every message and item, in the same
5482	// bytes. Within a turn the loop already appends; between turns the host
5483	// rebuilds the earlier turns from its records in a shorter form, which these
5484	// cases catch.
5485	//
5486	// They are hidden ("[.]") so the default run and CTest stay green while the
5487	// history still changes between turns. Run them by their tag:
5488	//   build/arm64/tests/agent/Release/agent_bridge_tests.app/Contents/MacOS/agent_bridge_tests "[history-prefix]"
5489	// Once one passes, drop the "." from its tags so every run guards the history.
5490	namespace {
5491	
5492	using nlohmann::ordered_json;
5493	
5494	// One scripted response: words, then a call if it makes one.
5495	struct ScriptedReply
5496	{
5497	    std::string text;
5498	    std::string call_id{};
5499	    std::string tool{};
5500	    json        input = json::object();
5501	};
5502	
5503	std::string sse(const json& event) { return "data: " + event.dump() + "\n\n"; }
5504	
5505	// A Messages API stream: signed thinking, the words, then the call.
5506	std::string anthropic_stream(const ScriptedReply& reply, const std::string& id)
5507	{
5508	    std::string out = sse(json{{"type", "message_start"},
5509	                               {"message", json{{"id", "msg_" + id}, {"usage", json{{"input_tokens", 100}, {"output_tokens", 1}}}}}});
5510	    const auto block = [&out](int index, const json& start, const json& delta) {
5511	        out += sse(json{{"type", "content_block_start"}, {"index", index}, {"content_block", start}});
5512	        out += sse(json{{"type", "content_block_delta"}, {"index", index}, {"delta", delta}});
5513	        out += sse(json{{"type", "content_block_stop"}, {"index", index}});
5514	    };
5515	    block(0, json{{"type", "thinking"}, {"thinking", "Thinking " + id + "."}, {"signature", ""}},
5516	          json{{"type", "signature_delta"}, {"signature", "signature-" + id}});
5517	    block(1, json{{"type", "text"}, {"text", ""}}, json{{"type", "text_delta"}, {"text", reply.text}});
5518	    if (!reply.call_id.empty())
5519	        block(2, json{{"type", "tool_use"}, {"id", reply.call_id}, {"name", reply.tool}, {"input", json::object()}},
5520	              json{{"type", "input_json_delta"}, {"partial_json", reply.input.dump()}});
5521	    out += sse(json{{"type", "message_delta"}, {"delta", json{{"stop_reason", reply.call_id.empty() ? "end_turn" : "tool_use"}}},
5522	                    {"usage", json{{"output_tokens", 10}}}});
5523	    return out + sse(json{{"type", "message_stop"}});
5524	}
5525	
5526	// A Responses API stream: an encrypted reasoning item, the message, then the
5527	// call, each with the item id and status the service gives it.
5528	std::string responses_stream(const ScriptedReply& reply, const std::string& id)
5529	{
5530	    json output = json::array(
5531	        {json{{"type", "reasoning"}, {"id", "rs_" + id}, {"summary", json::array()}, {"encrypted_content", "reasoning-" + id}},
5532	         json{{"type", "message"}, {"id", "msg_" + id}, {"status", "completed"}, {"role", "assistant"},
5533	              {"content", json::array({json{{"type", "output_text"}, {"text", reply.text}, {"annotations", json::array()}}})}}});
5534	    if (!reply.call_id.empty())
5535	        output.push_back(json{{"type", "function_call"}, {"id", "fc_" + id}, {"status", "completed"}, {"call_id", reply.call_id},
5536	                              {"name", reply.tool}, {"arguments", reply.input.dump()}});
5537	    return sse(json{{"type", "response.output_text.delta"}, {"delta", reply.text}}) +
5538	           sse(json{{"type", "response.completed"},
5539	                    {"response", json{{"output", output}, {"usage", json{{"input_tokens", 100}, {"output_tokens", 10}, {"total_tokens", 110}}}}}});
5540	}
