5542	// What the guard needs to know of one wire format.
5543	struct WireFormat
5544	{
5545	    std::string provider; // its ProviderProfile id
5546	    std::function<std::string(const ScriptedReply&, const std::string& id)> stream;
5547	    // The top-level fields that hold the prompt, in the order the provider
5548	    // reads them. Every other top-level field (model, thinking or reasoning
5549	    // settings, stream) must be the same on both requests.
5550	    std::vector<std::string> prompt_fields;
