5556	WireFormat anthropic_wire()
5557	{
5558	    // Its three cache breakpoints: one on the last tool and one on the system
5559	    // prompt, which stay where they are and are compared, and one on the
5560	    // newest user content, which moves to the newest one on every request. A
5561	    // breakpoint marks where to cache and is not part of the cached content
5562	    // (moving one is the documented pattern for a growing chat:
5563	    // platform.claude.com/docs/en/build-with-claude/prompt-caching), so the
5564	    // moving one is left out of the messages.
5565	    return {"anthropic", anthropic_stream, {"tools", "system", "messages"}, [](ordered_json& message) {
5566	                if (message.contains("content") && message["content"].is_array())
