5621	Prompt prompt_of(const WireFormat& wire, const std::string& body)
5622	{
5623	    ordered_json parsed = ordered_json::parse(body);
5624	    // Written again, the parsed body is the body itself, so each part below
5625	    // is exactly the bytes the service received for it.
5626	    REQUIRE(parsed.dump() == body);
