5631	        ordered_json value = parsed[field];
5632	        parsed.erase(field);
5633	        if (!value.is_array())
5634	            value = ordered_json::array({value});
5635	        for (std::size_t i = 0; i < value.size(); ++i) {
5636	            wire.forget_per_request(value[i]);
